<template>
  <div class="sec-bg-wrap" data-section="competency">
    <div class="sec-divider"></div>
    <section id="competency" class="sec" ref="sectionRef">
    <div class="sec-head reveal">
      <span class="sec-tag">{{ t('competency.tag') }}</span>
      <h2 class="sec-title">{{ t('competency.title') }}</h2>
    </div>
    <div class="comp-cols reveal">
      <div
        v-for="(card, i) in cards"
        :key="i"
        :class="['comp-col', `cc${i + 1}`]"
        ref="colRefs"
      >
        <div class="cc-num">{{ card.num }}</div>
        <span class="cc-icon">{{ card.icon }}</span>
        <div class="cc-title">{{ card.title }}</div>
        <div class="cc-sub" v-html="card.sub.replace(/\n/g, '<br>')" />
        <ul class="cc-items">
          <li v-for="item in card.items" :key="item">{{ item }}</li>
        </ul>
        <div class="cc-proof">
          <div class="cc-proof-label">{{ card.proofLabel }}</div>
          <div class="cc-proof-text">{{ card.proof }}</div>
        </div>
      </div>
    </div>
    </section>
  </div>
</template>

<script setup>
import { computed, ref, onMounted } from 'vue'
import { useI18n } from 'vue-i18n'

const { t, tm } = useI18n()
const sectionRef = ref(null)
const colRefs = ref([])

const cards = computed(() => tm('competency.cards'))

onMounted(() => {
  /* Scroll reveal */
  const observer = new IntersectionObserver(
    (entries) => {
      entries.forEach((entry, i) => {
        if (entry.isIntersecting) {
          setTimeout(() => entry.target.classList.add('visible'), i * 120)
          observer.unobserve(entry.target)
        }
      })
    },
    { threshold: 0.08 }
  )
  if (sectionRef.value) {
    sectionRef.value.querySelectorAll('.reveal').forEach(el => observer.observe(el))
  }

  /* 3D tilt on competency columns */
  document.querySelectorAll('.comp-col').forEach(col => {
    col.addEventListener('mousemove', e => {
      const r = col.getBoundingClientRect()
      const x = (e.clientX - r.left) / r.width - 0.5
      const y = (e.clientY - r.top) / r.height - 0.5
      col.style.transform = `perspective(600px) rotateY(${x * 6}deg) rotateX(${-y * 6}deg) translateY(-6px)`
    })
    col.addEventListener('mouseleave', () => {
      col.style.transform = ''
    })
  })
})
</script>

<style scoped>
/* ── Section Background ── */
.sec-bg-wrap {
  position: relative;
  width: 100%;
  background:
    repeating-linear-gradient(0deg, rgba(0,255,136,0.025) 0px, rgba(0,255,136,0.025) 1px, transparent 1px, transparent 44px),
    #030608;
}
.sec-bg-wrap::before {
  content: '';
  position: absolute;
  left: 0; top: 10%; width: 3px; height: 80%;
  background: #00ff88;
  border-radius: 0 2px 2px 0;
  z-index: 3;
}

.sec {
  padding: 80px 52px;
  max-width: 1280px;
  margin: 0 auto;
  position: relative;
  z-index: 2;
}
.sec-head { display: flex; align-items: center; gap: 16px; margin-bottom: 56px; }
.sec-tag {
  font-size: 10px;
  letter-spacing: 0.24em;
  text-transform: uppercase;
  color: var(--g);
  background: var(--g10);
  border: 1px solid var(--br2);
  padding: 5px 14px;
  border-radius: 2px;
  text-shadow: 0 0 12px rgba(0,255,136,0.4);
}
.sec-title {
  font-family: var(--disp);
  font-size: 38px;
  font-weight: 800;
  color: var(--tb);
  letter-spacing: -1.5px;
}

/* Three columns */
.comp-cols {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 14px;
}

.comp-col {
  background: var(--bg2);
  border-radius: 7px;
  padding: 24px 20px;
  border: 1px solid rgba(0,255,136,0.1);
  transition: all 0.35s;
  position: relative;
  overflow: hidden;
  cursor: none;
}
.comp-col::before {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 2px;
  opacity: 0;
  transition: opacity 0.35s;
}
.comp-col:hover {
  border-color: rgba(0,255,136,0.28);
  box-shadow: 0 20px 50px rgba(0,0,0,0.5);
}
.comp-col:hover::before { opacity: 1; }

.cc1::before { background: linear-gradient(90deg, var(--b), var(--g)); }
.cc2::before { background: linear-gradient(90deg, var(--g), var(--p)); }
.cc3::before { background: linear-gradient(90deg, var(--p), var(--a)); }

.cc-num {
  font-size: 10px;
  letter-spacing: 0.2em;
  color: rgba(0,255,136,0.2);
  margin-bottom: 14px;
}
.cc-icon {
  font-size: 26px;
  margin-bottom: 14px;
  display: block;
  line-height: 1;
}
.cc-title {
  font-family: var(--disp);
  font-size: 16px;
  font-weight: 700;
  margin-bottom: 6px;
}
.cc1 .cc-title { color: var(--b); }
.cc2 .cc-title { color: var(--g); }
.cc3 .cc-title { color: var(--p); }

.cc-sub {
  font-size: 11px;
  color: var(--tm);
  margin-bottom: 18px;
  line-height: 1.6;
}

.cc-items {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 7px;
  margin-bottom: 20px;
}
.cc-items li {
  font-size: 11px;
  color: var(--t);
  padding-left: 14px;
  position: relative;
  line-height: 1.55;
}
.cc-items li::before {
  content: '▸';
  position: absolute;
  left: 0;
  font-size: 10px;
  top: 2px;
}
.cc1 .cc-items li::before { color: var(--b); }
.cc2 .cc-items li::before { color: var(--g); }
.cc3 .cc-items li::before { color: var(--p); }

.cc-proof {
  border-top: 1px solid rgba(255,255,255,0.05);
  padding-top: 14px;
}
.cc-proof-label {
  font-size: 9px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: rgba(255,255,255,0.15);
  margin-bottom: 6px;
}
.cc-proof-text { font-size: 11px; line-height: 1.55; }
.cc1 .cc-proof-text { color: rgba(56,189,248,0.65); }
.cc2 .cc-proof-text { color: rgba(0,255,136,0.65); }
.cc3 .cc-proof-text { color: rgba(167,139,250,0.65); }

@media (max-width: 900px) {
  .sec { padding: 60px 24px; }
  .comp-cols { grid-template-columns: 1fr; gap: 12px; }
  .sec-title { font-size: 26px; }
  .comp-col:hover { transform: none !important; }
}
@media (max-width: 480px) {
  .sec { padding: 60px 16px; }
  .sec-title { font-size: 22px; }
}
</style>
