/**
 * 스크롤 진행바, 별자리 캔버스, 커스텀 커서, 자석 버튼, j/k 섹션 추적
 * App 마운트 후 호출 (자식 섹션 DOM이 모두 준비된 뒤)
 */
export function initGlobalEffects() {
  const progressEl = document.getElementById('progress')
  if (progressEl) {
    window.addEventListener('scroll', () => {
      const h = document.documentElement.scrollHeight - window.innerHeight
      if (h > 0) progressEl.style.width = (window.scrollY / h * 100) + '%'
    })
  }

  const canvas = document.getElementById('bg-canvas')
  if (!canvas) return
  const ctx = canvas.getContext('2d')
  let W, H
  let pts = []

  function resize() {
    W = canvas.width = window.innerWidth
    H = canvas.height = window.innerHeight
  }
  resize()
  window.addEventListener('resize', () => {
    resize()
    initPts()
  })

  function initPts() {
    pts = []
    const n = Math.floor(W * H / 12000)
    for (let i = 0; i < n; i++) {
      pts.push({
        x: Math.random() * W,
        y: Math.random() * H,
        vx: (Math.random() - 0.5) * 0.25,
        vy: (Math.random() - 0.5) * 0.25,
        r: Math.random() * 1.2 + 0.3,
        o: Math.random() * 0.4 + 0.15,
        phase: Math.random() * Math.PI * 2
      })
    }
  }
  initPts()

  let frame = 0
  function draw() {
    ctx.clearRect(0, 0, W, H)
    frame++
    pts.forEach(p => {
      p.x += p.vx
      p.y += p.vy
      if (p.x < 0) p.x = W
      if (p.x > W) p.x = 0
      if (p.y < 0) p.y = H
      if (p.y > H) p.y = 0
      const o = p.o * (0.5 + 0.5 * Math.sin(frame * 0.015 + p.phase))
      ctx.beginPath()
      ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2)
      ctx.fillStyle = `rgba(0,255,136,${o})`
      ctx.fill()
    })
    for (let i = 0; i < pts.length; i++) {
      for (let j = i + 1; j < pts.length; j++) {
        const dx = pts[i].x - pts[j].x
        const dy = pts[i].y - pts[j].y
        const d = Math.sqrt(dx * dx + dy * dy)
        if (d < 140) {
          ctx.beginPath()
          ctx.moveTo(pts[i].x, pts[i].y)
          ctx.lineTo(pts[j].x, pts[j].y)
          ctx.strokeStyle = `rgba(0,255,136,${(1 - d / 140) * 0.22})`
          ctx.lineWidth = 0.7
          ctx.stroke()
        }
      }
    }
    requestAnimationFrame(draw)
  }
  draw()

  let mx = 0, my = 0
  document.addEventListener('mousemove', e => {
    mx = e.clientX
    my = e.clientY
    pts.forEach(p => {
      const dx = mx - p.x, dy = my - p.y
      const d = Math.sqrt(dx * dx + dy * dy)
      if (d < 150) {
        p.vx += (dx / d) * 0.008
        p.vy += (dy / d) * 0.008
      }
    })
  })

  const cur = document.getElementById('cursor')
  const ring = document.getElementById('cursor-ring')
  let rx = 0, ry = 0

  if (cur && ring) {
    document.addEventListener('mousemove', e => {
      cur.style.left = e.clientX + 'px'
      cur.style.top = e.clientY + 'px'
    })

    const animRing = () => {
      rx += (mx - rx) * 0.1
      ry += (my - ry) * 0.1
      ring.style.left = rx + 'px'
      ring.style.top = ry + 'px'
      requestAnimationFrame(animRing)
    }
    animRing()

    const hoverSel =
      'a, button, .d-card, .stat-card, .comp-col, .sg, .chip, .proj-card, .etag, .lang-btn, .nav-gh'
    document.querySelectorAll(hoverSel).forEach(el => {
      el.addEventListener('mouseenter', () => {
        cur.style.width = '18px'
        cur.style.height = '18px'
        ring.style.width = '56px'
        ring.style.height = '56px'
        ring.style.borderColor = 'rgba(0,255,136,0.55)'
      })
      el.addEventListener('mouseleave', () => {
        cur.style.width = '10px'
        cur.style.height = '10px'
        ring.style.width = '38px'
        ring.style.height = '38px'
        ring.style.borderColor = 'rgba(0,255,136,0.35)'
      })
    })
  }

  document.querySelectorAll('.btn').forEach(btn => {
    btn.addEventListener('mousemove', e => {
      const r = btn.getBoundingClientRect()
      const x = (e.clientX - r.left - r.width / 2) * 0.3
      const y = (e.clientY - r.top - r.height / 2) * 0.3
      btn.style.transform = `translate(${x}px,${y}px)`
    })
    btn.addEventListener('mouseleave', () => {
      btn.style.transform = ''
    })
  })

  const SECTION_IDS = ['hero', 'competency', 'decisions', 'experience', 'skills', 'projects', 'contact']
  let currentSection = 'hero'

  function trackSection() {
    const thr = window.innerHeight * 0.35
    let best = 'hero'
    for (const id of SECTION_IDS) {
      const el = document.getElementById(id)
      if (el && el.getBoundingClientRect().top <= thr) best = id
    }
    currentSection = best
  }

  window.addEventListener('scroll', trackSection, { passive: true })
  trackSection()

  window.addEventListener('keydown', e => {
    const tag = e.target.tagName
    if (tag === 'INPUT' || tag === 'TEXTAREA') return
    const idx = SECTION_IDS.indexOf(currentSection)
    if (e.key === 'j' && idx < SECTION_IDS.length - 1) {
      document.getElementById(SECTION_IDS[idx + 1])?.scrollIntoView({ behavior: 'smooth' })
    }
    if (e.key === 'k' && idx > 0) {
      document.getElementById(SECTION_IDS[idx - 1])?.scrollIntoView({ behavior: 'smooth' })
    }
  })
}
